export function Debounce({
  delay = {{delay}},
  scenario = "{{scenario}}",
  showKeystrokes = {{showKeystrokes}},
  accent = "{{accent}}",
}) {
  const ticks = [10, 22, 30, 38];
  return (
    <div style={{ width: "100%", maxWidth: 320, padding: 16, background: "#FAF7F2", border: "1px solid #24143022", borderRadius: 12, fontFamily: "system-ui, sans-serif", fontSize: 12, color: "#241430aa" }}>
      <p style={{ margin: "0 0 8px", textTransform: "capitalize" }}>{scenario} events</p>
      <div style={{ position: "relative", height: 26, background: "#24143011", borderRadius: 999 }}>
        {showKeystrokes && ticks.map((t) => (
          <span key={t} style={{ position: "absolute", top: 4, left: `${t}%`, width: 3, height: 18, background: "#24143044", borderRadius: 2 }} />
        ))}
        <span style={{ position: "absolute", top: 3, left: `calc(38% + ${delay}px / 6)`, width: 20, height: 20, borderRadius: 999, background: accent }} />
      </div>
      <p style={{ margin: "8px 0 0" }}>Each event resets the {delay}ms timer &mdash; the request only fires once activity settles</p>
    </div>
  );
}
